import { theme } from '../../../../theme';

export const resolveThemeColor = (token?: string): string => {
  if (!token) {
    return theme.colors.interfaceLabelPrimary;
  }

  const color = theme.colors[token as keyof typeof theme.colors];

  return typeof color === 'string' ? color : theme.colors.interfaceLabelPrimary;
};
